package com.oms.supplychain.service.wms;
import org.springframework.stereotype.Component;
import org.w3c.dom.Element;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.stream.Collectors;
import static com.oms.supplychain.service.wms.WmsStore.*;
import static com.oms.supplychain.service.wms.QimenProtocol.*;
/** Standard CNJG protocol. Re-sends use an immutable XML snapshot and the original process code. */
@Component public class QimenProcessProtocol {
 private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
 static String value(Element e,String k){Element ch=child(e,k);return ch==null?"":ch.getTextContent().trim();}
 @SuppressWarnings("unchecked") public String create(Map<String,Object> t,Map<String,Object> recipe,Map<String,Object> stock){StringBuilder b=new StringBuilder("<request>");b.append(tag("processOrderCode",t.get("process_sn"))).append(tag("warehouseCode",t.get("external_warehouse"))).append(tag("ownerCode",t.get("external_owner"))).append(tag("orderType","CNJG")).append(tag("orderCreateTime",t.get("wire_time"))).append(tag("planTime",t.get("wire_time"))).append(tag("serviceType","ASSEMBLE".equals(t.get("operation"))?1:2)).append(tag("planQty",t.get("quantity"))).append(tag("remark",t.get("reason"))).append("<materialitems>");
  for(Map<String,Object> p:(List<Map<String,Object>>)recipe.get("components")){List<Map<String,Object>> holds=(List<Map<String,Object>>)stock.get("holds");boolean found=false;if("ASSEMBLE".equals(t.get("operation")))for(Map<String,Object> h:holds)if(h.get("sku_sn").equals(p.get("sku_sn"))){b.append(item(p.get("sku_sn"),h.get("quantity"),p.get("quantity"),h.get("batch_code"),t.get("external_owner")));found=true;}if(!found)b.append(item(p.get("sku_sn"),Math.multiplyExact(id(p.get("quantity")),id(t.get("quantity"))),p.get("quantity"),"",t.get("external_owner")));}
  b.append("</materialitems><productitems>");String batch="";if("DISASSEMBLE".equals(t.get("operation")))batch=text(((List<Map<String,Object>>)stock.get("holds")).get(0).get("batch_code"));b.append(item(t.get("sku_sn"),t.get("quantity"),1,batch,t.get("external_owner")));return b.append("</productitems></request>").toString();
 }
 private String item(Object sku,Object qty,Object ratio,Object batch,Object owner){return "<item>"+tag("itemCode",sku)+tag("quantity",qty)+tag("ratioQty",ratio)+tag("batchCode",batch)+tag("ownerCode",owner)+tag("inventoryType","ZP")+"</item>";}
 public WmsProtocol.Wire wire(Map<String,Object> c,String secret,String method,String body){Map<String,String> p=new TreeMap<>();p.put("app_key",text(c.get("app_key")));p.put("customerId",text(c.get("customer_id")));p.put("method",method);p.put("format","xml");p.put("sign_method","md5");p.put("v","2.0");p.put("timestamp",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(TIME));p.put("sign",sign(p,body,secret));return new WmsProtocol.Wire(text(c.get("endpoint"))+"?"+p.entrySet().stream().map(e->enc(e.getKey())+"="+enc(e.getValue())).collect(Collectors.joining("&")),body,"application/xml;charset=UTF-8");}
 public WmsProtocol.Reply reply(String body){Element root=parse(body);require("response".equals(root.getTagName())&&Arrays.asList("success","failure").contains(value(root,"flag")),"加工响应缺少明确业务结果");WmsProtocol.Reply r=new WmsProtocol.Reply();r.success="success".equals(value(root,"flag"));r.externalOrder=value(root,"processOrderId");r.message=value(root,"message");return r;}
 public Map<String,Object> callback(Map<String,Object> c,String secret,Map<String,String> p,String body){require("taobao.qimen.storeprocess.confirm".equals(p.get("method"))&&"md5".equals(p.get("sign_method"))&&"2.0".equals(p.get("v")),"加工回传协议不匹配");require(text(c.get("app_key")).equals(p.get("app_key"))&&text(c.get("customer_id")).equals(p.get("customerId")),"加工回传应用或客户不匹配");LocalDateTime sent;try{sent=LocalDateTime.parse(p.get("timestamp"),TIME);}catch(Exception e){throw new IllegalArgumentException("加工回传时间无效");}require(Math.abs(Duration.between(sent,LocalDateTime.now(ZoneId.of("Asia/Shanghai"))).getSeconds())<=600,"加工回传时间超出范围");require(MessageDigest.isEqual(sign(p,body,secret).getBytes(StandardCharsets.UTF_8),text(p.get("sign")).getBytes(StandardCharsets.UTF_8)),"加工回传验签失败");Element root=parse(body);require("request".equals(root.getTagName())&&"CNJG".equals(value(root,"orderType")),"加工回传单据类型无效");String message=value(root,"outBizCode"),sn=value(root,"processOrderCode");require(!message.isEmpty()&&message.length()<=100&&!sn.isEmpty(),"加工回传单号或消息编号缺失");long qty=id(value(root,"actualQty"));require(qty>0&&qty<=100000000,"加工回传实际套数无效");return map("process_sn",sn,"external_order",value(root,"processOrderId"),"message_id",message,"quantity",qty,"warehouse",value(root,"warehouseCode"),"owner",value(root,"ownerCode"),"materials",lines(root,"materialitems"),"products",lines(root,"productitems"));}
 private List<Map<String,Object>> lines(Element root,String name){Element group=child(root,name);require(group!=null,"加工回传缺少投入或产出明细");List<Element> items=children(group,"item");if(items.isEmpty()&&child(group,"itemCode")!=null)items=Arrays.asList(group);require(!items.isEmpty()&&items.size()<=500,"加工回传明细须为1至500行");List<Map<String,Object>> result=new ArrayList<>();for(Element item:items){String sku=value(item,"itemCode"),batch=value(item,"batchCode"),type=value(item,"inventoryType");long q=id(value(item,"quantity"));require(!sku.isEmpty()&&sku.length()<=128&&!batch.isEmpty()&&batch.length()<=128&&q>0&&q<=100000000&&Arrays.asList("ZP","CC","CP","JS","XS").contains(type),"加工回传SKU、批次、数量或库存类型无效");result.add(map("sku_sn",sku,"batch_code",batch,"quantity",q,"inventory_type",type,"owner",value(item,"ownerCode")));}return result;}
}
